/**
 * Tests correctness for large n and sharpness of upper bound in API doc
 * JIRA: MATH-241
 */
@Test
public void testBinomialCoefficientLarge() throws Exception {
    // This tests all legal and illegal values for n <= 200.
    for (int n = 0; n <= 200; n++) {
        for (int k = 0; k <= n; k++) {
            long exactResult = -1;
            boolean shouldThrow = false;
            boolean didThrow = false;
            try {
                BinomialCoefficient.value(n, k);
            } catch (ArithmeticException ex) {
                didThrow = true;
            }
            try {
                exactResult = BinomialCoefficientTest.binomialCoefficient(n, k);
            } catch (ArithmeticException ex) {
                shouldThrow = true;
            }
            if (!shouldThrow && exactResult > 1) {
                Assert.assertEquals(n + " choose " + k, 1., BinomialCoefficientDouble.value(n, k) / exactResult, 1e-10);
            }
        }
    }
    final int n = 10000;
    final double actualOverExpected = BinomialCoefficientDouble.value(n, 3) / BinomialCoefficientTest.binomialCoefficient(n, 3);
    Assert.assertEquals(1, actualOverExpected, 1e-10);
}

