@Test
public void testComputeRoots() {
    final double tol = Math.ulp(1d);
    final org.apache.commons.math3.complex.RootsOfUnity cmRoots = new org.apache.commons.math3.complex.RootsOfUnity();
    for (int n = -10; n < 11; n++) {
        final int absN = Math.abs(n);
        if (n != 0) {
            cmRoots.computeRoots(n);
            final RootsOfUnity roots = new RootsOfUnity(n);
            for (int k = 0; k < absN; k++) {
                final Complex z = roots.getRoot(k);
                Assert.assertEquals("n=" + n + " k=" + k, cmRoots.getReal(k), z.getReal(), tol);
                Assert.assertEquals("n=" + n + " k=" + k, cmRoots.getImaginary(k), z.getImaginary(), tol);
            }
        }
    }
}

