    Assert.assertFalse(Precision.equals(153.0, 153.00000000000006, 1));
    Assert.assertTrue(Precision.equals(153.0, 152.99999999999997, 1));
    Assert.assertFalse(Precision.equals(153, 152.99999999999994, 1));
